code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    start = next(( (r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 2), None)
    if start is None:
        return out
    r,c=start
    if r == 0:
        dr,dc=1,0
    elif r == h-1:
        dr,dc=-1,0
    elif c == 0:
        dr,dc=0,1
    else:
        dr,dc=0,-1
    q=deque([(r,c,dr,dc)])
    seen=set()
    while q:
        r,c,dr,dc=q.popleft()
        state=(r,c,dr,dc)
        if state in seen:
            continue
        seen.add(state)
        # Travel straight through the corridor until the next wall or edge.
        rr,cc=r,c
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 8:
            if grid[rr][cc] == 0:
                out[rr][cc]=2
            rr+=dr; cc+=dc
        if not (0 <= rr < h and 0 <= cc < w):
            continue
        # The wall turns the trace along its near side. Use the nearest opening
        # in each direction; if none exists, extend that branch to the grid edge.
        wr,wc=rr,cc
        if dr != 0:
            ar,ac=wr-dr,wc
            axis=(-1,0)
            length=h
            anchor=ar
            def wall_gap(t): return grid[t][wc] != 8
            def pos(t): return (t,ac)
            def wallpos(t): return (t,wc)
        else:
            ar,ac=wr,wc-dc
            length=w
            anchor=ac
            def wall_gap(t): return grid[wr][t] != 8
            def pos(t): return (ar,t)
            def wallpos(t): return (wr,t)
        # At the wall's perpendicular coordinate, find first opening in each direction.
        for step in (-1,1):
            t=anchor
            endpoint=None
            while 0 <= t < length:
                if wall_gap(t):
                    endpoint=t
                    break
                t+=step
            if endpoint is None:
                endpoint=0 if step < 0 else length-1
            lo,hi=sorted((anchor,endpoint))
            for x in range(lo,hi+1):
                pr,pc=pos(x)
                if grid[pr][pc] == 0:
                    out[pr][pc]=2
            if wall_gap(endpoint):
                gr,gc=wallpos(endpoint)
                # Cross the opening and resume in the original direction.
                nr,nc=gr+dr,gc+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8:
                    q.append((nr,nc,dr,dc))
    return out
'''
